double candidate(List<int> sortedLuminances, int target, int k) {
  final int n = sortedLuminances.length;
  if (k <= 0 || k > n) {
    return -1.0;
  }
  if (n == 1) {
    return sortedLuminances[0].toDouble();
  }


  int lo = 0;
  int hi = n - k;
  while (lo < hi) {
    final int mid = lo + (hi - lo) ~/ 2;
    final int leftVal = sortedLuminances[mid];
    final int rightVal = sortedLuminances[mid + k];
    if (leftVal + rightVal >= 2 * target) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }

  final int windowLeft = sortedLuminances[lo];
  final int windowRight = sortedLuminances[lo + k - 1];
  final int distLeft = target - windowLeft;
  final int distRight = windowRight - target;
  if (distLeft > distRight) {
    return windowLeft.toDouble();
  }
  return windowRight.toDouble();
}

void main() {}

