import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')

void candidate() {

  final random = Random(0);
  final int numSamples = 1000000;

  double f(double x) => x * x;

  final double a = 0.0;  
  final double b = 1.0;  

  double sum = 0.0;
  for (int i = 0; i < numSamples; i++) {

    double x = a + (b - a) * random.nextDouble();
    sum += f(x);
  }

  double integral = (b - a) * sum / numSamples;

  print('Monte Carlo Integration Results:');
  print('Function: f(x) = x^2');
  print('Integration bounds: [$a, $b]');
  print('Number of samples: $numSamples');
  print('Estimated integral: $integral');
  print('Exact value: ${1.0/3.0}');
  print('Error: ${(integral - 1.0/3.0).abs()}');

  print('\n--- Additional example: Estimating π using Monte Carlo ---');

  int pointsInsideCircle = 0;

  for (int i = 0; i < numSamples; i++) {
    double x = random.nextDouble();
    double y = random.nextDouble();

    if (x * x + y * y <= 1.0) {
      pointsInsideCircle++;
    }
  }

  double piEstimate = 4.0 * pointsInsideCircle / numSamples;

  print('Estimating π using quarter circle method:');
  print('Points inside circle: $pointsInsideCircle');
  print('Total points: $numSamples');
  print('Estimated π: $piEstimate');
  print('Actual π: ${pi}');
  print('Error: ${(piEstimate - pi).abs()}');

  print('\n--- Monte Carlo integration of sin(x) from 0 to π ---');

  double lowerBound = 0.0;
  double upperBound = pi;
  double sinSum = 0.0;

  for (int i = 0; i < numSamples; i++) {
    double x = lowerBound + (upperBound - lowerBound) * random.nextDouble();
    sinSum += sin(x);
  }

  double sinIntegral = (upperBound - lowerBound) * sinSum / numSamples;

  print('Function: f(x) = sin(x)');
  print('Integration bounds: [0, π]');
  print('Estimated integral: $sinIntegral');
  print('Exact value: 2.0');
  print('Error: ${(sinIntegral - 2.0).abs()}');

  print('\n--- Monte Carlo volume estimation (3D) ---');

  double volumeSum = 0.0;

  for (int i = 0; i < numSamples; i++) {
    double x = random.nextDouble();
    double y = random.nextDouble();
    volumeSum += x * y;
  }

  double volumeEstimate = volumeSum / numSamples;

  print('3D Surface: z = x*y');
  print('Domain: x,y ∈ [0,1]');
  print('Estimated volume: $volumeEstimate');
  print('Exact value: 0.25');
  print('Error: ${(volumeEstimate - 0.25).abs()}');
}

void main() {}

