import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')

int candidate(String misspelled, List<String> candidates) {
  int charDiffs(String a, String b) {
    int count = 0;
    int len = a.length < b.length ? a.length : b.length;
    for (int i = 0; i < len; i++) {
      if (a[i] != b[i]) count++;
    }
    count += (a.length - len).abs();
    return count;
  }
  List<int> indices = List.generate(candidates.length, (i) => i);
  indices.sort((a, b) {
    int diffA = charDiffs(misspelled, candidates[a]);
    int diffB = charDiffs(misspelled, candidates[b]);
    if (diffA != diffB) return diffA.compareTo(diffB);
    return candidates[a].compareTo(candidates[b]);
  });
  return indices.isEmpty ? -1 : indices[0];
}

void main() {}

