@pragma('vm:entry-point')

List<String> candidate(List<String> logLines) {
  int countDistinctPrimeFactors(int n) {
    Set<int> factors = {};
    int d = 2;
    while (d * d <= n) {
      while (n % d == 0) {
        factors.add(d);
        n ~/= d;
      }
      d++;
    }
    if (n > 1) factors.add(n);
    return factors.length;
  }

  String toBase(int n, int b) {
    if (n == 0) return '0';
    const String digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    String result = '';
    while (n > 0) {
      result = digits[n % b] + result;
      n ~/= b;
    }
    return result;
  }

  bool isPalindrome(String s) {
    int i = 0, j = s.length - 1;
    while (i < j) {
      if (s[i] != s[j]) return false;
      i++;
      j--;
    }
    return true;
  }

  List<String> results = [];
  for (String line in logLines) {
    List<String> parts = line.split(':');
    if (parts.length != 2) continue;
    int? code = int.tryParse(parts[1]);
    if (code == null || code < 1) continue;
    int base = countDistinctPrimeFactors(code) + 2;
    String baseRep = toBase(code, base);
    if (isPalindrome(baseRep)) {
      results.add(line);
    }
  }
  return results;
}

