  }

  Map<String, int> step(
    int index,
    int charge,
    int cycles,
    int spilled,
    int emptyHits,
  ) {
    if (index == changes.length) {
      return {
        'cycles': cycles,
        'finalCharge': charge,
        'spilled': spilled,
        'emptyHits': emptyHits,
      };
    }

    int delta = changes[index];
    int nextCharge = charge;
    int nextCycles = cycles;
    int nextSpilled = spilled;
    int nextEmptyHits = emptyHits;

    if (delta >= 0) {
      int filled = charge + delta;
      if (filled >= capacity) {
        if (charge < capacity && delta > 0) {
          nextCycles++;
        }
        nextSpilled += filled - capacity;
        nextCharge = capacity;
      } else {
        nextCharge = filled;
      }
    } else {
      int drained = charge + delta;
      if (drained <= 0) {
        nextCharge = 0;
        nextEmptyHits++;
      } else {
        nextCharge = drained;
      }
    }

    return step(index + 1, nextCharge, nextCycles, nextSpilled, nextEmptyHits);
  }

  return step(0, 0, 0, 0, 0);
