      final c = password.codeUnitAt(i);
      switch (parts[0]) {
        case 'L': if (c >= 97 && c <= 122) count++; break;
        case 'U': if (c >= 65 && c <= 90) count++; break;
        case 'D': if (c >= 48 && c <= 57) count++; break;
        case 'S': if (c < 48 || (c > 57 && c < 65) || (c > 90 && c < 97) || c > 122) count++; break;
        case 'N': count++; break;
      }
    }
    if (count >= min) met++;
  }
  return met;
}

