List<int> candidate(List<int> grid, int n) {
  List<int> result = [];
  if (n <= 0 || grid.isEmpty) return result;

  int numStrips = (n + 1) ~/ 2;

  for (int strip = 0; strip < numStrips; strip++) {
    int rightCol = n - 1 - strip * 2;
    int leftCol = rightCol - 1;

    bool goingUp = (strip % 2 == 0);

    for (int i = 0; i < n; i++) {
      int row = goingUp ? (n - 1 - i) : i;

      for (int c = 0; c < 2; c++) {
        int col = (c == 0) ? rightCol : leftCol;

        if (col < 0 || col >= n) continue;

        if ((row + col) % 7 == 0) continue;

        result.add(grid[row * n + col]);
      }
    }
  }

  return result;
}

