double candidate(List<int> readings) {
  if (readings.isEmpty) return 0.0;

  int excellent = 0;
  int good = 0;
  int fair = 0;
  int weak = 0;
  int dead = 0;
  for (final int r in readings) {
    if (r >= -50) {
      excellent++;
    } else if (r >= -60) {
      good++;
    } else if (r >= -70) {
      fair++;
    } else if (r >= -80) {
      weak++;
    } else {
      dead++;
    }
  }

  final List<int> counts = [excellent, good, fair, weak, dead];
  final List<double> weights = [1.0, 0.75, 0.5, 0.25, 0.0];

  double base = 0.0;
  for (int i = 0; i < counts.length; i++) {
    base += counts[i] * weights[i];
  }

  int firstNonEmpty = -1;
  int lastNonEmpty = -1;
  for (int i = 0; i < counts.length; i++) {
    if (counts[i] > 0) {
      if (firstNonEmpty == -1) firstNonEmpty = i;
      lastNonEmpty = i;
    }
  }

  int gaps = 0;
  if (firstNonEmpty != -1) {
    for (int i = firstNonEmpty; i <= lastNonEmpty; i++) {
      if (counts[i] == 0) gaps++;
    }
  }

  final double score = base - gaps.toDouble();
  return score < 0.0 ? 0.0 : score;
}

