double candidate(List<int> tempos, List<String> artists, int maxTempoDrops) {
  if (tempos.isEmpty || artists.isEmpty || tempos.length != artists.length) {
    return 0.0;
  }

  final Map<String, int> artistCounts = <String, int>{};
  int left = 0;
  int drops = 0;
  double bestScore = 0.0;

  for (int right = 0; right < tempos.length; right++) {
    final String artist = artists[right];
    artistCounts[artist] = (artistCounts[artist] ?? 0) + 1;

    if (right > 0 && tempos[right] < tempos[right - 1]) {
      drops++;
    }

    while (drops > maxTempoDrops || artistCounts[artist]! > 2) {
      final String leftArtist = artists[left];
      artistCounts[leftArtist] = artistCounts[leftArtist]! - 1;

      if (artistCounts[leftArtist] == 0) {
        artistCounts.remove(leftArtist);
      }

      if (left + 1 <= right && tempos[left + 1] < tempos[left]) {
        drops--;
      }

      left++;
    }

    double score = (right - left + 1).toDouble();

    if (right > left &&
        (tempos[right] - tempos[left]).abs() <= 2 &&
        artistCounts.length >= 2) {
      score += 0.5;
    }

    if (score > bestScore) {
      bestScore = score;
    }
  }

  return bestScore;
}

