Set<int> candidate(List<String> commands) {
  Set<int> state = {};
  List<Set<int>> history = [{}];

  for (String command in commands) {
    List<String> parts = command.trim().split(RegExp(r'\s+'));
    if (parts.isEmpty || parts[0].isEmpty) continue;
    String action = parts[0];

    if (action == 'CALL' && parts.length == 2) {
      int? floor = int.tryParse(parts[1]);
      if (floor != null && floor >= 1 && floor <= 100) {
        if (!state.contains(floor)) {
          state = Set.from(state)..add(floor);
          history.add(Set.from(state));
        }
      }
    } else if (action == 'CANCEL' && parts.length == 2) {
      int? floor = int.tryParse(parts[1]);
      if (floor != null && floor >= 1 && floor <= 100) {
        if (state.contains(floor)) {
          state = Set.from(state)..remove(floor);
          history.add(Set.from(state));
        }
      }
    } else if (action == 'SWAP' && parts.length == 3) {
      int? f1 = int.tryParse(parts[1]);
      int? f2 = int.tryParse(parts[2]);
      if (f1 != null && f2 != null && f1 >= 1 && f1 <= 100 && f2 >= 1 && f2 <= 100) {
        if (f1 != f2 && state.contains(f1)) {
          state = Set.from(state)..remove(f1)..add(f2);
          history.add(Set.from(state));
        }
      }
    } else if (action == 'UNDO' && parts.length == 1) {
      if (history.length > 1) {
        history.removeLast();
        state = Set.from(history.last);
      }
    }
  }
  return state;
}

