  }

  int n = starts.length;
  List<int> missing = List.filled(n, 0);
  int occupiedBefore = 0;

  for (int i = 0; i < n; i++) {
    missing[i] = starts[i] - 1 - occupiedBefore;
    occupiedBefore += (ends[i] - starts[i] + 1);
  }

  List<String> results = [];
  for (int k in queries) {
    int left = 0;
    int right = n - 1;
    int ans = -1;

