      int mid = left + (right - left) ~/ 2;
      if (missing[mid] >= k) {
        ans = mid;
        right = mid - 1;
      } else {
        left = mid + 1;
      }
    }

    if (ans == -1) {
      results.add((ends[n - 1] + k - missing[n - 1]).toString());
    } else if (ans == 0) {
      results.add(k.toString());
    } else {
      results.add((ends[ans - 1] + k - missing[ans - 1]).toString());
    }
  }

  return results;
}

