    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a.abs();
  }

  bool isPrime(int n) {
    if (n < 2) {
      return false;
    }
    for (int i = 2; i * i <= n; i++) {
      if (n % i == 0) {
        return false;
      }
    }
    return true;
  }

  int length = red.length;
  if (green.length < length) {
    length = green.length;
  }
  if (blue.length < length) {
    length = blue.length;
  }

  double score = 0.0;

  for (int i = 0; i < length; i++) {
    int mix = (red[i] * 3 + green[i] * 5 + blue[i] * 7) % modulus;
    int channelGcd = gcd(gcd(red[i], green[i]), blue[i]);

    if (isPrime(channelGcd)) {
      score += mix.isEven ? 1.0 : 0.5;
    } else if (mix.isEven) {
      score += 0.25;
    }
  }

  return score;
}

