bool candidate(int requestMask, int lockedMask, int startFloor, int floorCount) {
  if (floorCount <= 0 || floorCount > 30) {
    return false;
  }

  if (startFloor < 0 || startFloor >= floorCount) {
    return false;
  }

  int validMask = (1 << floorCount) - 1;

  if (((requestMask | lockedMask) & ~validMask) != 0) {
    return false;
  }

  if ((requestMask & lockedMask) != 0) {
    return false;
  }

  if (requestMask == 0) {
    return true;
  }

  int rotated = ((requestMask >> startFloor) |
          (requestMask << (floorCount - startFloor))) &
      validMask;

  bool seenRequest = false;
  bool seenGap = false;
  int requestCount = 0;

  for (int i = 0; i < floorCount; i++) {
    bool hasRequest = ((rotated >> i) & 1) == 1;

    if (hasRequest) {
      requestCount++;

      if (seenGap) {
        return false;
      }

      seenRequest = true;
    } else if (seenRequest) {
      seenGap = true;
    }
  }

  return requestCount <= (floorCount ~/ 2) + 1;
}

