Set<int> candidate(List<int> shelfCodes, int base) {
  if (base < 2) {
    return <int>{};
  }

  bool isPrime(int value) {
    if (value < 2) {
      return false;
    }
    for (int i = 2; i * i <= value; i++) {
      if (value % i == 0) {
        return false;
      }
    }
    return true;
  }

  int gcd(int a, int b) {
    while (b != 0) {
      int temp = a % b;
      a = b;
      b = temp;
    }
    return a.abs();
  }

  Set<int> groups = <int>{};

  for (int code in shelfCodes) {
    if (code <= 0) {
      continue;
    }

    int n = code;
    int digitSum = 0;
    List<int> digits = <int>[];

    while (n > 0) {
      int digit = n % base;
      digits.add(digit);
      digitSum += digit;
      n ~/= base;
    }

    if (!isPrime(digitSum)) {
      continue;
    }

    int reversedValue = 0;
    for (int digit in digits) {
      reversedValue = reversedValue * base + digit;
    }

    int sharedFactor = gcd(code, reversedValue);
    if (sharedFactor > 1) {
      groups.add(sharedFactor + digitSum);
    }
  }

  return groups;
}

