    List<int> digits = <int>[];

    while (n > 0) {
      int digit = n % base;
      digits.add(digit);
      digitSum += digit;
      n ~/= base;
    }

    if (!isPrime(digitSum)) {
      continue;
    }

    int reversedValue = 0;
    for (int digit in digits) {
      reversedValue = reversedValue * base + digit;
    }

    int sharedFactor = gcd(code, reversedValue);
    if (sharedFactor > 1) {
      groups.add(sharedFactor + digitSum);
    }
  }

  return groups;
}

