  for (int idx = 0; idx < readings.length; idx++) {
    int j = idx;
    while (j + 1 < readings.length && readings[j] < readings[j + 1]) j++;
    if (j - idx + 1 >= 3 && readings[idx] < 0 && readings[j] > 0) count++;
  }
  return count;
}

