class SkipNode<T extends Comparable> {
  T? value;
  List<SkipNode<T>?> forward;

  SkipNode(this.value, int level) : forward = List.filled(level + 1, null);
}

class SkipList<T extends Comparable> {
  static const int _maxLevel = 16;
  static const double _p = 0.5;

  final SkipNode<T> _header = SkipNode<T>(null, _maxLevel);
  int _level = 0;
  final Random _random = Random(0);

  int _randomLevel() {
    int lvl = 0;
    while (_random.nextDouble() < _p && lvl < _maxLevel) {
      lvl++;
    }
    return lvl;
  }

  void insert(T value) {
    List<SkipNode<T>?> update = List.filled(_maxLevel + 1, null);
    SkipNode<T>? x = _header;

    for (int i = _level; i >= 0; i--) {
      while (x!.forward[i] != null && x.forward[i]!.value!.compareTo(value) < 0) {
        x = x.forward[i];
      }
      update[i] = x;
    }
    x = x!.forward[0];

    if (x == null || x.value != value) {
      int lvl = _randomLevel();
      if (lvl > _level) {
        for (int i = _level + 1; i <= lvl; i++) {
          update[i] = _header;
        }
        _level = lvl;
      }
      SkipNode<T> newNode = SkipNode<T>(value, lvl);
      for (int i = 0; i <= lvl; i++) {
        newNode.forward[i] = update[i]!.forward[i];
        update[i]!.forward[i] = newNode;
      }
    }
  }

  bool search(T value) {
    SkipNode<T>? x = _header;
    for (int i = _level; i >= 0; i--) {
      while (x!.forward[i] != null && x.forward[i]!.value!.compareTo(value) < 0) {
        x = x.forward[i];
      }
    }
    x = x!.forward[0];
    if (x != null && x.value == value) {
      return true;
    }
    return false;
  }

  bool delete(T value) {
    List<SkipNode<T>?> update = List.filled(_maxLevel + 1, null);
    SkipNode<T>? x = _header;
    for (int i = _level; i >= 0; i--) {
      while (x!.forward[i] != null && x.forward[i]!.value!.compareTo(value) < 0) {
        x = x.forward[i];
      }
      update[i] = x;
    }
    x = x!.forward[0];
    if (x != null && x.value == value) {
      for (int i = 0; i <= _level; i++) {
        if (update[i]!.forward[i] != x) break;
        update[i]!.forward[i] = x.forward[i];
      }
      while (_level > 0 && _header.forward[_level] == null) {
        _level--;
      }
      return true;
    }
    return false;
  }

  void printList() {
    print("Skip List Levels:");
    for (int i = _level; i >= 0; i--) {
      SkipNode<T>? node = _header.forward[i];
      String line = "Level $i: ";
      while (node != null) {
        line += "${node.value} ";
        node = node.forward[i];
      }
      print(line);
    }
  }
}

