  final Set<int> uniqueSums = {};
  int currentSum = 0;
  for (int i = 0; i < rgbValues.length; i++) {
    currentSum += rgbValues[i];
    if (i >= windowSize) currentSum -= rgbValues[i - windowSize];
    if (i >= windowSize - 1) uniqueSums.add(currentSum);
  }
  return uniqueSums;
}

