double candidate(List<String> log) {

  final List<List<double>> stack = <List<double>>[];

  final List<List<Object>> history = <List<Object>>[];
  double total = 0.0;
  for (final String entry in log) {
    final List<String> parts = entry.split(' ');
    if (parts[0] == 'IN') {
      stack.add(<double>[double.parse(parts[1]), double.parse(parts[2])]);
      history.add(<Object>['IN']);
    } else if (parts[0] == 'OUT') {
      double need = double.parse(parts[1]);
      double costSum = 0.0;
      final List<List<double>> taken = <List<double>>[];
      while (need > 0 && stack.isNotEmpty) {
        final List<double> top = stack.last;
        final double take = need < top[0] ? need : top[0];
        top[0] -= take;
        need -= take;
        costSum += take * top[1];
        double removedFlag = 0.0;
        if (top[0] == 0.0) {
          stack.removeLast();
          removedFlag = 1.0;
        }
        taken.add(<double>[take, top[1], removedFlag]);
      }
      total += costSum;
      history.add(<Object>['OUT', taken, costSum]);
    } else {

      if (history.isEmpty) continue;
      final List<Object> last = history.removeLast();
      if (last[0] == 'IN') {
        if (stack.isNotEmpty) stack.removeLast();
      } else {
        final List<List<double>> taken = last[1] as List<List<double>>;
        total -= (last[2] as double);
        for (int i = taken.length - 1; i >= 0; i--) {
          if (taken[i][2] == 1.0) {
            stack.add(<double>[taken[i][0], taken[i][1]]);
          } else {
            stack.last[0] += taken[i][0];
          }
        }
      }
    }
  }
  return total;
}

void main() {}

