Map<String, int> candidate(List<String> sortedMorse) {
  Map<String, int> result = {};
  Set<String> seen = {};
  for (int i = 0; i < sortedMorse.length; i++) {
    if (seen.contains(sortedMorse[i])) continue;
    seen.add(sortedMorse[i]);
    int lo = 0, hi = i, first = i;
    while (lo <= hi) {
      int mid = (lo + hi) ~/ 2;
      if (sortedMorse[mid] == sortedMorse[i]) {
        first = mid;
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    }
    result[sortedMorse[i]] = first;
  }
  return result;
}

