Map<String, int> candidate(List<int> cents) {
  if (cents.isEmpty) return {};
  int totalOriginal = cents.fold(0, (a, b) => a + b);
  int targetTotal = ((totalOriginal + 2) ~/ 5) * 5;
  List<int> result = List.filled(cents.length, 0);

  bool backtrack(int index, int currentSum) {
    if (index == cents.length) return currentSum == targetTotal;
    int down = (cents[index] ~/ 5) * 5;
    int up = ((cents[index] + 4) ~/ 5) * 5;

    result[index] = down;
    if (backtrack(index + 1, currentSum + down)) return true;

    if (up != down) {
      result[index] = up;
      if (backtrack(index + 1, currentSum + up)) return true;
    }
    return false;
  }

  backtrack(0, 0);

  Map<String, int> resultMap = {};
  for (int i = 0; i < cents.length; i++) {
    resultMap['item_$i'] = result[i];
  }
  resultMap['total'] = targetTotal;
  return resultMap;
}

