    Point(5, 3),
    Point(2, 5),
    Point(-1, 3),
  ];

  List<List<Point<double>>> triangulate(List<Point<double>> poly) {
    if (poly.length < 3) return [];
    List<int> V = List.generate(poly.length, (i) => i);

    bool isCCW(List<Point<double>> pts) {
      double area = 0;
      for (int i = 0; i < pts.length; i++) {
        int j = (i + 1) % pts.length;
        area += (pts[j].x - pts[i].x) * (pts[j].y + pts[i].y);
      }
      return area < 0;
    }

    bool isConvex(Point<double> prev, Point<double> curr, Point<double> next) {
      double cross = (curr.x - prev.x) * (next.y - curr.y) -
          (curr.y - prev.y) * (next.x - curr.x);
      return cross < 0; 
    }

    bool pointInTriangle(Point<double> p, Point<double> a, Point<double> b, Point<double> c) {
      double area = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
      double s = ((a.y - c.y) * (p.x - c.x) + (c.x - a.x) * (p.y - c.y)) / area;
      double t = ((c.y - b.y) * (p.x - c.x) + (b.x - c.x) * (p.y - c.y)) / area;
      double u = 1 - s - t;
      return s > 0 && t > 0 && u > 0;
    }

    if (!isCCW(poly)) {
      poly = poly.reversed.toList();
    }

    List<List<Point<double>>> triangles = [];
    int n = poly.length;
    int count = 0; 

    while (V.length > 3 && count < 1000) {
      bool earFound = false;
