        int next = V[(i + 1) % V.length];

        Point<double> pPrev = poly[prev];
        Point<double> pCurr = poly[curr];
        Point<double> pNext = poly[next];

        if (isConvex(pPrev, pCurr, pNext)) {

          bool hasPointInside = false;
          for (int j = 0; j < V.length; j++) {
            if (j == (i - 1 + V.length) % V.length ||
                j == i ||
                j == (i + 1) % V.length) continue;
            if (pointInTriangle(poly[V[j]], pPrev, pCurr, pNext)) {
              hasPointInside = true;
              break;
            }
          }
          if (!hasPointInside) {
            triangles.add([pPrev, pCurr, pNext]);
            V.removeAt(i);
            earFound = true;
            break;
          }
        }
      }
