  List<int> sorted = List.from(packets)..sort();
  return _canMerge(sorted, threshold, <String>{});
}

bool _canMerge(List<int> current, int threshold, Set<String> visited) {
  if (current.length == 1) return true;
  String state = current.join(',');
  if (visited.contains(state)) return false;
  visited.add(state);

  for (int i = 0; i < current.length; i++) {
    for (int j = i + 1; j < current.length; j++) {
      if ((current[i] - current[j]).abs() <= threshold) {
        List<int> next = [];
        for (int k = 0; k < current.length; k++) {
          if (k != i && k != j) {
            next.add(current[k]);
          }
        }
        next.add(current[i] + current[j]);
        next.sort();
        if (_canMerge(next, threshold, visited)) {
          return true;
        }
      }
    }
  }
  return false;
}

void main() {}

