bool candidate(List<int> itemCents, int targetCents, int roundToNearest) {
  if (roundToNearest <= 0) return false;

  int baseSum = 0;
  int tieCount = 0;

  for (int item in itemCents) {
    if (item < 0) return false;

    final int lower = (item ~/ roundToNearest) * roundToNearest;
    final int upper = lower + roundToNearest;
    final int dist = item - lower;
    final int twiceDist = dist * 2;

    if (twiceDist < roundToNearest) {
      baseSum += lower;
    } else if (twiceDist > roundToNearest) {
      baseSum += upper;
    } else {
      baseSum += lower;
      tieCount += 1;
    }
  }

  final int diff = targetCents - baseSum;
  if (diff < 0) return false;
  if (diff % roundToNearest != 0) return false;

  final int neededUps = diff ~/ roundToNearest;
  return neededUps <= tieCount;
}

