    int digit = n % 10;
    bool prime = digit > 1;
    for (int d = 2; d * d <= digit; d++) {
      if (digit % d == 0) {
        prime = false;
        break;
      }
    }
    if (prime) {
      seal += digit * 2;
    } else if (digit % 2 == 0) {
