int candidate(List<String> deck, List<String> customOrder) {
  if (deck.isEmpty) return 0;
  Map<String, int> rankMap = {};
  for (int i = 0; i < customOrder.length; i++) {
    rankMap[customOrder[i]] = i;
  }
  List<int> ranks = deck.map((card) => rankMap[card]!).toList();
  List<int> temp = List.filled(ranks.length, 0);
  return _mergeSortCount(ranks, temp, 0, ranks.length - 1);
}

int _mergeSortCount(List<int> arr, List<int> temp, int left, int right) {
  int invCount = 0;
  if (left < right) {
    int mid = (left + right) >> 1;
    invCount += _mergeSortCount(arr, temp, left, mid);
    invCount += _mergeSortCount(arr, temp, mid + 1, right);
    invCount += _merge(arr, temp, left, mid, right);
  }
  return invCount;
}

int _merge(List<int> arr, List<int> temp, int left, int mid, int right) {
  int i = left, j = mid + 1, k = left, invCount = 0;
  while (i <= mid && j <= right) {
    if (arr[i] <= arr[j]) {
      temp[k++] = arr[i++];
    } else {
      temp[k++] = arr[j++];
      invCount += (mid - i + 1);
    }
  }
  while (i <= mid) temp[k++] = arr[i++];
  while (j <= right) temp[k++] = arr[j++];
  for (i = left; i <= right; i++) arr[i] = temp[i];
  return invCount;
}

