List<String> candidate(String log) {
  if (log.isEmpty) return [];
  final cycles = log.split('|');
  final result = <String>[];
  for (final cycle in cycles) {
    if (cycle.isEmpty) continue;
    final colonIdx = cycle.indexOf(':');
    if (colonIdx == -1) continue;
    final cycleNumber = cycle.substring(0, colonIdx);
    final rest = cycle.substring(colonIdx + 1);
    final semiIdx = rest.indexOf(';');
    if (semiIdx == -1) continue;
    final encoding = rest.substring(0, semiIdx);
    final checksumStr = rest.substring(semiIdx + 1);
    final checksum = int.tryParse(checksumStr);
    if (checksum == null) continue;
    int sum = 0;
    final decoded = StringBuffer();
    int i = 0;
    while (i < encoding.length) {
      int num = 0;
      bool hasDigit = false;
      while (i < encoding.length) {
        final code = encoding.codeUnitAt(i);
        if (code >= 48 && code <= 57) {
          num = num * 10 + (code - 48);
          hasDigit = true;
          i++;
        } else {
          break;
        }
      }
      if (!hasDigit || i >= encoding.length) break;
      final level = encoding[i];
      i++;
      sum += num;
      decoded.write(level * num);
    }
    if (sum == checksum) {
      result.add('Cycle $cycleNumber: ${decoded.toString()}');
    }
  }
  return result;
}

