    (rowMap[row] ??= []).add(col);
  }

  final balanced = <int>{};
  for (final entry in rowMap.entries) {
    final rowIndex = entry.key;
    final cols = entry.value..sort();
    final count = cols.length;
    if (count == 0) continue;

    final prefix = List<int>.filled(count, 0);
    for (var i = 0; i < count; i++) {
      prefix[i] = cols[i] + (i > 0 ? prefix[i - 1] : 0);
    }

    final totalSum = prefix[count - 1];
    for (var i = 0; i < count; i++) {
      final col = cols[i];
      final leftCount = i;
      final rightCount = count - i - 1;
      final leftSum = i > 0 ? prefix[i - 1] : 0;
      final rightSum = totalSum - prefix[i];

      final leftDistance = col * leftCount - leftSum;
      final rightDistance = rightSum - col * rightCount;

      if (leftDistance == rightDistance) {
        balanced.add(rowIndex * seatsPerRow + col);
      }
    }
