    final df = tf - cf;
    final dr = tr - cr;
    final aligned = df == 0 || dr == 0 || df.abs() == dr.abs();
    if (!aligned) {
      final from = String.fromCharCode(97 + cf) + (cr + 1).toString();
      return 'BREAK:' + from + '>' + names[i];
    }
    final sf = df.sign;
    final sr = dr.sign;
    while (cf != tf || cr != tr) {
      cf += sf;
      cr += sr;
      buf.write(',' + String.fromCharCode(97 + cf) + (cr + 1).toString());
    }
  }
  return buf.toString();
}

