double candidate(String manifest) {
  List<String> splitEscaped(String text, String separator) {
    final parts = <String>[];
    final current = StringBuffer();
    bool escaped = false;

    for (int i = 0; i < text.length; i++) {
      final char = text[i];
      if (escaped) {
        current.write(char);
        escaped = false;
      } else if (char == '\\') {
        escaped = true;
      } else if (char == separator) {
        parts.add(current.toString());
        current.clear();
      } else {
        current.write(char);
      }
    }

    if (escaped) {
      current.write('\\');
    }

    parts.add(current.toString());
    return parts;
  }

  double total = 0.0;

  for (final record in splitEscaped(manifest, ';')) {
    if (record.isEmpty) {
      continue;
    }

    final fields = splitEscaped(record, '|');
    if (fields.length != 4) {
      continue;
    }

    final zone = fields[0];
    final expected = int.tryParse(fields[1]);
    final scanned = int.tryParse(fields[2]);

    if (expected == null || scanned == null) {
      continue;
    }

    if (expected < 0 || scanned < 0) {
      continue;
    }

    double variance = (expected - scanned).abs().toDouble();
    final tags = splitEscaped(fields[3], ',');

    if (tags.contains('fragile')) {
      variance *= 2.0;
    }

    if (tags.contains('bulk')) {
      variance /= 2.0;
    }

    if (tags.contains('frozen')) {
      variance += 0.25;
    }

    if (zone.startsWith('R') && variance > 0.0) {
      variance += 0.5;
    }

    total += variance;
  }

  return total;
}

