List<String> candidate(String log) {

  if (log.isEmpty) return <String>[];
  String binOf(int n) {
    if (n <= 50) return 'STRONG';
    if (n <= 60) return 'GOOD';
    if (n <= 70) return 'FAIR';
    if (n <= 80) return 'WEAK';
    return 'DEAD';
  }
  bool isAlnum(int c) =>
      (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122);
  final out = <String>[];
  var name = StringBuffer();
  int val = 0;
  int state = 0; 
  for (int i = 0; i < log.length; i++) {
    final c = log.codeUnitAt(i);
    if (state == 0) {
      if (isAlnum(c)) {
        name.write(log[i]);
      } else if (c == 61 && name.isNotEmpty) {
        state = 1;
      } else {
        return ['ERR@$i'];
      }
    } else if (state == 1) {
      if (c == 45) { state = 2; } else { return ['ERR@$i']; }
    } else if (state == 2) {
      if (c >= 48 && c <= 57) { val = c - 48; state = 3; } else { return ['ERR@$i']; }
    } else {
      if (c >= 48 && c <= 57) {
        val = val * 10 + (c - 48);
      } else if (c == 44) {
        out.add('$name:${binOf(val)}');
        name = StringBuffer();
        val = 0;
        state = 0;
      } else {
        return ['ERR@$i'];
      }
    }
  }
  if (state != 3) return ['ERR@${log.length}'];
  out.add('$name:${binOf(val)}');
  return out;
}

void main() {}

