  List<int> testNumbers = [17, 24, 29, 35, 47, 50, 67, 100];
  print('\nPrimality test for specific numbers:');
  for (int num in testNumbers) {
    if (num <= n) {
      print('$num is ${prime[num] ? "prime" : "not prime"}');
    } else {
      print('$num is outside the range (> $n)');
    }
  }
}

