      final escaped = value
          .replaceAll(r'\', r'\\')
          .replaceAll('"', r'\"')
          .replaceAll('\b', r'\b')
          .replaceAll('\f', r'\f')
          .replaceAll('\n', r'\n')
          .replaceAll('\r', r'\r')
          .replaceAll('\t', r'\t');
      return '"$escaped"';
    } else if (value is List) {
      return '[${value.map(customJsonEncode).join(',')}]';
    } else if (value is Map) {
      return '{' +
          value.entries
              .map((e) =>
                  '${customJsonEncode(e.key.toString())}:${customJsonEncode(e.value)}')
              .join(',') +
          '}';
    } else {
      throw ArgumentError('Unsupported type: ${value.runtimeType}');
    }
  }

  final data = {
    'name': 'Dart',
    'version': 3,
