      'list': [1, 2, 3],
      'emptyMap': {},
      'nullValue': null,
    },
    'specialChars': 'He said: "Hello\nWorld"\tTab'
  };

  final customEncoded = customJsonEncode(data);
  final dartEncoded = jsonEncode(data);

  print('Custom JSON:');
  print(customEncoded);
  print('\nDart jsonEncode:');
