String candidate(String initialRow, List<String> commands) {
  List<int> seats = initialRow.split('').map(int.parse).toList();
  List<List<int>> undoStack = [];
  for (String cmd in commands) {
    if (cmd == 'U') {
      if (undoStack.isNotEmpty) {
        List<int> last = undoStack.removeLast();
        seats[last[0]] += last[1];
      }
    } else if (cmd.startsWith('B ')) {
      int n = int.parse(cmd.substring(2));
      for (int i = 0; i < seats.length; i++) {
        if (seats[i] >= n) {
          seats[i] -= n;
          undoStack.add([i, n]);
          break;
        }
      }
    }
  }
  return seats.join();
}

