List<String> candidate(int playlistAvailability, int minContinuousMinutes) {
  if (minContinuousMinutes <= 0) return [];
  List<String> blocks = [];
  int avail = playlistAvailability;

  while (avail != 0) {

    int lowestOne = avail & (-avail);
    int start = lowestOne.bitLength - 1;

    int shifted = avail >>> start;

    int inverted = ~shifted;
    int invLowest = inverted & (-inverted);

    int runLength = (invLowest == 0) ? 64 : (invLowest.bitLength - 1);
    int end = start + runLength - 1;

    if (runLength >= minContinuousMinutes) {
      blocks.add("$start-$end");
    }

    if (end == 63) {
      avail = 0;
    } else {
      avail = (avail >>> (end + 1)) << (end + 1);
    }
  }
  return blocks;
}

