int candidate(List<int> signals) {
  if (signals.isEmpty) return 0;
  int binOf(int s) {
    if (s >= -50) return 0;
    if (s >= -60) return 1;
    if (s >= -70) return 2;
    return 3;
  }
  Set<int> required = {};
  for (int s in signals) {
    required.add(binOf(s));
  }
  int totalReq = required.length;
  Map<int, int> counts = {};
  int formed = 0;
  int minLen = signals.length + 1;
  int left = 0;
  for (int right = 0; right < signals.length; right++) {
    int b = binOf(signals[right]);
    counts[b] = (counts[b] ?? 0) + 1;
    if (counts[b] == 1) formed++;
    while (formed == totalReq) {
      int len = right - left + 1;
      if (len < minLen) minLen = len;
      int lb = binOf(signals[left]);
      counts[lb] = counts[lb]! - 1;
      if (counts[lb] == 0) formed--;
      left++;
    }
  }
  return minLen > signals.length ? 0 : minLen;
}

void main() {}

