  int left = 0;
  for (int right = 0; right < rolls.length; right++) {
    while (right - left + 1 > windowSize) left++;
    if (right - left + 1 == windowSize) {
      bool isSteady = true;
      for (int k = left; k <= right; k++) if (rolls[k] != rolls[left]) isSteady = false;
      if (isSteady) steadyStarts.add(left);
    }
  }
  return steadyStarts;
}

