void candidate(List<String> args) {





  if (args.isEmpty) {
    print('Usage: dart run coin_change.dart <amount> <coin1> <coin2> ...');
    return;
  }

  final int? amountParsed = int.tryParse(args[0]);
  if (amountParsed == null || amountParsed < 0) {
    print('Invalid amount "${args[0]}". Amount must be a non-negative integer.');
    return;
  }
  final int amount = amountParsed;

  if (args.length < 2) {
    print('Provide at least one coin denomination.');
    return;
  }

  final List<int> coins = <int>[];
  for (int i = 1; i < args.length; i++) {
    final int? coin = int.tryParse(args[i]);
    if (coin == null || coin <= 0) {
      print('Invalid coin denomination "${args[i]}". Must be a positive integer.');
      return;
    }
    coins.add(coin);
  }

  coins.sort();                     
  const int inf = 1 << 30;          
  final List<int> dp = List<int>.filled(amount + 1, inf);
  final List<int> prevCoin = List<int>.filled(amount + 1, -1);

  dp[0] = 0;                        

  for (final int coin in coins) {
    for (int sum = coin; sum <= amount; sum++) {
      if (dp[sum - coin] + 1 < dp[sum]) {
        dp[sum] = dp[sum - coin] + 1;
        prevCoin[sum] = coin;       
      }
    }
  }

  if (dp[amount] == inf) {
    print('Impossible to make $amount with coins $coins.');
    return;
  }

  print('Minimum number of coins required: ${dp[amount]}');

  final List<int> combination = <int>[];
  int current = amount;
  while (current > 0) {
    final int coin = prevCoin[current];
    combination.add(coin);
    current -= coin;
  }
  print('One optimal combination: $combination');
}

