Set<int> candidate(
  List<int> timetableMinutes,
  int hubMinute,
  int minSpacing,
) {
  int normalize(int value) {
    int result = value % 1440;
    return result < 0 ? result + 1440 : result;
  }

  int circularDistance(int a, int b) {
    int diff = (a - b).abs();
    return diff > 720 ? 1440 - diff : diff;
  }

  int normalizedHub = normalize(hubMinute);
  Set<int> uniqueMinutes = <int>{};

  for (final minute in timetableMinutes) {
    uniqueMinutes.add(normalize(minute));
  }

  List<int> ordered = uniqueMinutes.toList();

  ordered.sort((a, b) {
    int distanceA = circularDistance(a, normalizedHub);
    int distanceB = circularDistance(b, normalizedHub);

    if (distanceA != distanceB) {
      return distanceA - distanceB;
    }

    int offsetA = (a - normalizedHub) % 1440;
    int offsetB = (b - normalizedHub) % 1440;
    return offsetB - offsetA;
  });

  List<int> accepted = <int>[];

  for (final minute in ordered) {
    bool fits = true;

    for (final kept in accepted) {
      if (circularDistance(minute, kept) < minSpacing) {
        fits = false;
        break;
      }
    }

    if (fits) {
      accepted.add(minute);
    }
  }

  return accepted.toSet();
}

void main() {}

