  if (tallies.length == 1) {
    return tallies[0] >= threshold;
  }
  int mid = tallies.length ~/ 2;
  List<int> left = tallies.sublist(0, mid);
  List<int> right = tallies.sublist(mid);
  int leftSum = 0;
  for (int v in left) {
    leftSum += v;
  }
  int rightSum = 0;
  for (int v in right) {
    rightSum += v;
  }
  if (leftSum >= threshold || rightSum >= threshold) return true;
  return candidate(left, threshold - rightSum) ||
         candidate(right, threshold - leftSum);
}

