bool candidate(int moduleRow, int moduleCol, int version) {
  if (version < 1 || version > 40) return false;
  int gridSize = 17 + 4 * version;
  if (moduleRow < 0 || moduleRow >= gridSize) return false;
  if (moduleCol < 0 || moduleCol >= gridSize) return false;

  int a = moduleRow + 1;
  int b = moduleCol + 1;
  while (b != 0) {
    int temp = b;
    b = a % b;
    a = temp;
  }
  int gcdValue = a;

  if ((version + 1) % gcdValue != 0) return false;

