  final cycleLength = phaseDurations.fold<int>(0, (sum, d) => sum + d);
  if (cycleLength == 0 || greenPhases.isEmpty) {
    return waits;
  }
  final phaseStarts = <int>[];
  var cumulative = 0;
  for (final d in phaseDurations) {
    phaseStarts.add(cumulative);
    cumulative += d;
  }
  final sortedGreens = greenPhases.toList()..sort();
  for (final arrival in arrivalTimes) {
    final offset = arrival % cycleLength;
    var phaseIndex = 0;
    for (var i = 0; i < phaseDurations.length; i++) {
      if (offset < phaseStarts[i] + phaseDurations[i]) {
        phaseIndex = i;
        break;
      }
    }
    if (greenPhases.contains(phaseIndex)) {
      waits.add(0);
      continue;
    }
    var nextGreenStart = -1;
    for (var j = phaseIndex + 1; j < phaseDurations.length; j++) {
      if (greenPhases.contains(j)) {
        nextGreenStart = phaseStarts[j];
        break;
      }
    }
    if (nextGreenStart == -1) {
      nextGreenStart = cycleLength + phaseStarts[sortedGreens.first];
    }
    waits.add(nextGreenStart - offset);
  }
  return waits;
}

