    for (int i = 0; i < entry.length; i++) {
      if (entry[i] == '=') {
        if (pivot != -1) {
          pivot = -2;
          break;
        }
        pivot = i;
      }
    }
    if (pivot <= 0 || pivot >= entry.length - 1) {
      out.add('syntax');
      continue;
