bool candidate(String line) {
  if (line.isEmpty) return false;
  List<String> tokens = [];
  StringBuffer current = StringBuffer();
  bool inQuotes = false;
  bool inBrackets = false;
  bool escape = false;
  for (int i = 0; i < line.length; i++) {
    String ch = line[i];
    if (escape) {
      current.write(ch);
      escape = false;
      continue;
    }
    if (ch == '\\') {
      escape = true;
      current.write(ch);
      continue;
    }
    if (ch == '"' && !inBrackets) {
      inQuotes = !inQuotes;
      current.write(ch);
      continue;
    }
    if (ch == '[' && !inQuotes) {
      inBrackets = true;
      current.write(ch);
      continue;
    }
    if (ch == ']' && !inQuotes) {
      inBrackets = false;
      current.write(ch);
      continue;
    }
    if (ch == ' ' && !inQuotes && !inBrackets) {
      if (current.length > 0) {
        tokens.add(current.toString());
        current.clear();
      }
      continue;
    }
    current.write(ch);
  }
  if (current.length > 0) tokens.add(current.toString());
  if (tokens.length != 7) return false;
  if (!tokens[0].contains('.') || tokens[0].split('.').length != 4) return false;
  if (!tokens[3].startsWith('"') || !tokens[3].endsWith('"')) return false;
  String status = tokens[5];
  if (status.length != 3) return false;
  int code = int.tryParse(status) ?? 0;
  return code >= 100 && code <= 599;
}

void main() {}

