double candidate(List<int> times, List<double> energies, double targetEnergy) {
  if (times.isEmpty) return 0.0;
  if (times.length == 1) return times[0].toDouble();
  if (targetEnergy <= energies[0]) return times[0].toDouble();
  if (targetEnergy >= energies[energies.length - 1]) {
    return times[times.length - 1].toDouble();
  }
  int low = 0;
  int high = energies.length - 2;
  while (low < high) {
    int mid = low + (high - low + 1) ~/ 2;
    if (energies[mid] <= targetEnergy) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  int i = low;
  double e0 = energies[i];
  double e1 = energies[i + 1];
  int t0 = times[i];
  int t1 = times[i + 1];
  return t0.toDouble() + (targetEnergy - e0) / (e1 - e0) * (t1 - t0);
}

