import 'dart:async';
import 'dart:convert';
import 'dart:io';

@pragma('vm:never-inline')
@pragma('vm:entry-point')

void candidate() {

  final edges = [
    [0, 1, 10],
    [0, 2, 6],
    [0, 3, 5],
    [1, 3, 15],
    [2, 3, 4],
  ];

  const n = 4;

  List<int> parent = List.generate(n, (i) => i);
  List<int> rank = List.filled(n, 0);

  int find(int u) {
    if (parent[u] != u) {
      parent[u] = find(parent[u]);
    }
    return parent[u];
  }

  void union(int u, int v) {
    int ru = find(u);
    int rv = find(v);
    if (ru == rv) return;
    if (rank[ru] < rank[rv]) {
      parent[ru] = rv;
    } else if (rank[ru] > rank[rv]) {
      parent[rv] = ru;
    } else {
      parent[rv] = ru;
      rank[ru]++;
    }
  }

  edges.sort((a, b) => a[2].compareTo(b[2]));

  List<List<int>> mst = [];
  int mstWeight = 0;

  for (var edge in edges) {
    int u = edge[0], v = edge[1], w = edge[2];
    if (find(u) != find(v)) {
      mst.add([u, v, w]);
      mstWeight += w;
      union(u, v);
    }
    if (mst.length == n - 1) break;
  }

  print('Edges in the Minimum Spanning Tree:');
  for (var edge in mst) {
    print('${edge[0]} -- ${edge[1]} == ${edge[2]}');
  }
  print('Total weight of MST: $mstWeight');
}

void main() {}

