import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')

void candidate() {

  List<int> values = [60, 100, 120];
  List<int> weights = [10, 20, 30];
  int n = values.length;
  int capacity = 50;

  List<List<int>> dp = List.generate(
      n + 1, (_) => List<int>.filled(capacity + 1, 0, growable: false),
      growable: false);

  for (int i = 0; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {
      if (i == 0 || w == 0) {
        dp[i][w] = 0;
      } else if (weights[i - 1] <= w) {
        dp[i][w] = dp[i - 1][w].clamp(
            dp[i - 1][w],
            values[i - 1] + dp[i - 1][w - weights[i - 1]]);

      } else {
        dp[i][w] = dp[i - 1][w];
      }
    }
  }

  print('Maximum value in Knapsack = ${dp[n][capacity]}');

  int res = dp[n][capacity];
  int w = capacity;
  List<int> itemsIncluded = [];
  for (int i = n; i > 0 && res > 0; i--) {
    if (res != dp[i - 1][w]) {

      itemsIncluded.add(i - 1);
      res -= values[i - 1];
      w -= weights[i - 1];
    }
  }

  print('Items included (0-based indices): ${itemsIncluded.reversed.toList()}');
}

void main() {}

