  for (String log in logs) {
    if (log == 'ADD' || log == 'SUB' || log == 'MUL' || log == 'DIV' || log == 'MAX' || log == 'MIN') {
      double b = stack.removeLast();
      double a = stack.removeLast();
      if (log == 'ADD') stack.add(a + b);
      else if (log == 'SUB') stack.add(a - b);
      else if (log == 'MUL') stack.add(a * b);
      else if (log == 'DIV') stack.add(a / b);
      else if (log == 'MAX') stack.add(a > b ? a : b);
      else if (log == 'MIN') stack.add(a < b ? a : b);
    } else {
      stack.add(double.parse(log));
    }
  }
  return stack.isEmpty ? 0.0 : stack.last;
}

