String candidate(List<int> starts, List<int> durations, List<String> sequences, int queryStart, int queryEnd) {
  if (queryStart > queryEnd) return '';
  StringBuffer rle = StringBuffer();
  int count = 0;
  String? lastBase;
  for (int d = queryStart; d <= queryEnd; d++) {
    int bestIdx = -1;
    int? maxStart;
    for (int i = 0; i < starts.length; i++) {
      if (durations[i] <= 0) continue;
      if (starts[i] <= d && d < starts[i] + durations[i]) {
        if (maxStart == null || starts[i] > maxStart!) {
          maxStart = starts[i];
          bestIdx = i;
        }
      }
    }
    String base = 'N';
    if (bestIdx != -1) {
      int offset = d - starts[bestIdx];
      if (offset < sequences[bestIdx].length) {
        base = sequences[bestIdx][offset];
      }
    }
    if (lastBase == null) {
      lastBase = base;
      count = 1;
    } else if (base == lastBase) {
      count++;
    } else {
      rle.write('$count$lastBase');
      lastBase = base;
      count = 1;
    }
  }
  if (lastBase != null) {
    rle.write('$count$lastBase');
  }
  return rle.toString();
}

