bool candidate(List<List<double>> samples, int maxRunLength, double maxWeightedDrift) {
  if (samples.length <= 1) return true;
  final seen = <double>{};
  for (final s in samples) {
    if (!seen.add(s[0])) return false;
  }
  final sorted = List<List<double>>.from(samples)
    ..sort((a, b) => a[0].compareTo(b[0]));
  final deltas = <double>[];
  for (int i = 1; i < sorted.length; i++) {
    final d = sorted[i][1] - sorted[i - 1][1];
    if (d == 0.0) return false;
    deltas.add(d);
  }
  int runLen = 1;
  for (int i = 1; i < deltas.length; i++) {
    if ((deltas[i] > 0) == (deltas[i - 1] > 0)) {
      runLen++;
      if (runLen > maxRunLength) return false;
    } else {
      runLen = 1;
    }
  }
  double drift = 0.0;
  for (final d in deltas) {
    drift = drift * 0.5 + d.abs();
    if (drift > maxWeightedDrift) return false;
  }
  if (deltas.length >= 2) {
    final hasPos = deltas.any((d) => d > 0);
    final hasNeg = deltas.any((d) => d < 0);
    if (!hasPos || !hasNeg) return false;
  }
  return true;
}

