Map<String, int> candidate(List<List<int>> batteryReadings, int fullCapacity) {
  if (batteryReadings.isEmpty || fullCapacity <= 0) {
    return {'cycles': 0, 'depth': 0};
  }

  int minReading = batteryReadings[0][0];
  int maxReading = batteryReadings[0][0];

  for (final reading in batteryReadings) {
    for (final val in reading) {
      if (val < 0 || val > fullCapacity) {
        throw ArgumentError('Readings must be between 0 and fullCapacity');
      }
      if (val < minReading) minReading = val;
      if (val > maxReading) maxReading = val;
    }
  }

  int range = maxReading - minReading;
  if (range == 0) {
    return {'cycles': 0, 'depth': 0};
  }

  int left = 1;
  int right = range;
  int bestCycles = 0;
  int bestDepth = 0;

  while (left <= right) {
    int depth = left + (right - left) ~/ 2;
    int cycles = _countDisjointCycles(batteryReadings, depth, fullCapacity);

    if (cycles > 0) {
      if (cycles > bestCycles || (cycles == bestCycles && depth > bestDepth)) {
        bestCycles = cycles;
        bestDepth = depth;
      }
      left = depth + 1;
    } else {
      right = depth - 1;
    }
  }

  return {'cycles': bestCycles, 'depth': bestDepth};
}

int _countDisjointCycles(List<List<int>> readings, int depth, int capacity) {
  int count = 0;
  for (final session in readings) {
