    for (int i = 1; i < session.length; i++) {
      if (session[i] < sessionMin) sessionMin = session[i];
      if (session[i] > sessionMax) sessionMax = session[i];
    }
    if (sessionMax - sessionMin >= depth) {
      count++;
    }
  }
  return count;
}

