      continue;
    }
    int total = 0;
    bool invalid = false;
    for (int i = 0; i < section.length; i++) {
      String c = section[i];
      if (c == '#') {
        invalid = true;
        break;
      }
      if (c != '+' && c != '-') {
        continue;
      }
      int j = i + 1;
      while (j < section.length && section[j] == ' ') {
        j++;
      }
      int value = 0;
      bool foundDigit = false;
      while (j < section.length) {
        int code = section.codeUnitAt(j);
        if (code < 48 || code > 57) {
          break;
        }
        foundDigit = true;
        value = value * 10 + code - 48;
        j++;
      }
      if (!foundDigit) {
        continue;
      }
      if (j < section.length && section[j] == '!') {
        value *= 2;
      }
      total += c == '+' ? value : -value;
      i = j - 1;
    }
    if (!invalid && total != 0) {
      loads.add(total);
    }
  }
  return loads;
}

