int candidate(String program) {
  var deck = List<int>.generate(52, (i) => i);
  int i = 0;
  while (i < program.length) {
    int repeat = 0;
    while (i < program.length) {
      int code = program.codeUnitAt(i);
      if (code < 48 || code > 57) break;
      repeat = repeat * 10 + (code - 48);
      i++;
    }
    if (repeat == 0) repeat = 1;
    if (i >= program.length) break;
    String cmd = program[i];
    i++;
    for (int r = 0; r < repeat; r++) {
      switch (cmd) {
        case 'd':
          if (deck.isNotEmpty) deck.removeAt(0);
          break;
        case 's':
          int n = deck.length;
          int half = (n + 1) ~/ 2;
          var first = deck.sublist(0, half);
          var second = deck.sublist(half);
          var shuffled = <int>[];
          for (int j = 0; j < second.length; j++) {
            shuffled.add(first[j]);
            shuffled.add(second[j]);
          }
          if (first.length > second.length) shuffled.add(first.last);
          deck = shuffled;
          break;
        case 'r':
          deck = deck.reversed.toList();
          break;
        case 't':
          if (deck.isNotEmpty) deck.add(deck.removeAt(0));
          break;
        case 'b':
          if (deck.isNotEmpty) deck.insert(0, deck.removeLast());
          break;
        case 'c':
          int n = deck.length;
          int half = n ~/ 2;
          deck = deck.sublist(half) + deck.sublist(0, half);
          break;
      }
    }
  }
  return deck.isEmpty ? -1 : deck.first;
}

