class CuckooHash {
  late List<int?> table1;
  late List<int?> table2;
  final int size;

  CuckooHash(this.size) {
    table1 = List<int?>.filled(size, null);
    table2 = List<int?>.filled(size, null);
  }

  int hash1(int key) => key % size;

  int hash2(int key) => (key * 2 + 1) % size; 

  bool insert(int key) {
    int h1 = hash1(key);
    if (table1[h1] == null) {
      table1[h1] = key;
      return true;
    }

    int h2 = hash2(key);
    if (table2[h2] == null) {
      table2[h2] = key;
      return true;
    }

    int currentKey = key;
    bool useTable1 = true; 
    for (int i = 0; i < size * 2; i++) { 
      if (useTable1) {
        int index = hash1(currentKey);
        int? evicted = table1[index];
        table1[index] = currentKey;
        if (evicted == null) return true;
        currentKey = evicted;
        useTable1 = false;
      } else {
        int index = hash2(currentKey);
        int? evicted = table2[index];
        table2[index] = currentKey;
        if (evicted == null) return true;
        currentKey = evicted;
        useTable1 = true;
      }
    }

    return false;
  }

  bool lookup(int key) {
    return table1[hash1(key)] == key || table2[hash2(key)] == key;
  }

  void printTables() {
    print('Table 1: $table1');
    print('Table 2: $table2');
  }
}

