void candidate() {

  List<int> arr = [2, 3, 1, 4, 5, 0, 6];
  int n = arr.length;

  int logn = (log(n) / log(2)).floor() + 1;

  List<List<int>> st = List.generate(n, (_) => List.filled(logn, 0));

  for (int i = 0; i < n; i++) {
    st[i][0] = arr[i];
  }

  for (int j = 1; j < logn; j++) {
    for (int i = 0; i + (1 << j) <= n; i++) {
      st[i][j] = min(st[i][j - 1], st[i + (1 << (j - 1))][j - 1]);
    }
  }

