import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')

void candidate() {

  List<int> arr = [2, 3, 1, 4, 5, 0, 6];
  int n = arr.length;

  int logn = (log(n) / log(2)).floor() + 1;

  List<List<int>> st = List.generate(n, (_) => List.filled(logn, 0));

  for (int i = 0; i < n; i++) {
    st[i][0] = arr[i];
  }

  for (int j = 1; j < logn; j++) {
    for (int i = 0; i + (1 << j) <= n; i++) {
      st[i][j] = min(st[i][j - 1], st[i + (1 << (j - 1))][j - 1]);
    }
  }

  int query(int L, int R) {
    int len = R - L + 1;
    int k = (log(len) / log(2)).floor();
    return min(st[L][k], st[R - (1 << k) + 1][k]);
  }

  print('Min from 0 to 5: ${query(0, 5)}'); 
  print('Min from 1 to 3: ${query(1, 3)}'); 
  print('Min from 2 to 6: ${query(2, 6)}'); 
  print('Min from 4 to 4: ${query(4, 4)}'); 
}

