Map<String, int> candidate(List<String> rows) {
  if (rows.isEmpty) {
    return {'tallest': 0, 'total': 0};
  }

  int rowCount = rows.length;
  int colCount = rows[0].length;
  List<List<int>> dp = List.generate(
    rowCount,
    (_) => List.filled(colCount, 0),
  );

  int tallest = 0;
  int total = 0;

  for (int r = rowCount - 1; r >= 0; r--) {
    for (int c = 0; c < colCount; c++) {
      if (rows[r][c] == '#') {
        dp[r][c] = 1;

        if (r + 1 < rowCount && c > 0 && c + 1 < colCount) {
          int left = dp[r + 1][c - 1];
          int middle = dp[r + 1][c];
          int right = dp[r + 1][c + 1];

          int smallest = left < middle ? left : middle;
          if (right < smallest) {
            smallest = right;
          }

          dp[r][c] += smallest;
        }

        total += dp[r][c];
        if (dp[r][c] > tallest) {
          tallest = dp[r][c];
        }
      }
    }
  }

  return {'tallest': tallest, 'total': total};
}

void main() {}

