bool candidate(List<int> editLog, int maxDepth) {
  List<int> stack = [];
  for (int edit in editLog) {
    if (edit > 0) {
      if (stack.length >= maxDepth) return false;
      stack.add(edit);
    } else if (edit == -1) {
      if (stack.isEmpty) return false;
      stack.removeLast();
    }
  }
  return stack.isEmpty;
}

